Method.Source:
    int  active()
    {
        FormDataSource form_ds = this;
        FormRun formRun = form_ds.formRun();
        
        int ret;
        
        ret = next active();

        form_ds.object(fieldNum(WHSPhysDimUOM, ItemId)).allowEdit(false);
        formRun.control(FormRun.controlId(formControlStr(WHSPhysDimUOM, DisplayLengthSystemUOM))).visible(false);
        formRun.control(FormRun.controlId(formControlStr(WHSPhysDimUOM, DisplayMassSystemUOM))).visible(false);

        return ret;
    }
